-- main.sql : probabilidades de falla de cada enlace tras el sismo M8.8 (USGS official20100227063411530_30)
-- Generado 2026-11-18 16:17 por scripts/modelo_falla.py  (fuente=circular, K=1.0)
-- Modelo: ruptura circular Strasser 2010 (R = 159.3 km) -> Youngs 1997 (PGA) -> Wald 1999 (MMI, PGV) -> ALA 2001 (RR) -> Poisson
-- Requiere el esquema red.aristas ya construido (sql/06_construir_red_topologia.sql)

DROP TABLE IF EXISTS red.prob_falla;
CREATE TABLE red.prob_falla(
  arista_id int PRIMARY KEY, capa text, longitud_m double precision,
  dist_fuente_km double precision, pga_g double precision, mmi double precision,
  pgv_cm_s double precision, tasa_reparacion_km double precision, p_falla double precision);
